def process(path):
    img = Image.open(path)
    variants = preprocess_variants(img)

    texts = []
    for vname, vimg in variants:
        for cfg in OCR_CONFIGS:
            try:
                t = ocr(vimg, config=cfg)
            except Exception:
                t = ""
            texts.append(t)

    # Date: first valid date from any OCR text
    date = None
    for t in texts:
        d = find_date_in_text(t)
        if d is not None:
            date = d
            break

    # Total: pick result with best tier (lowest index)
    best = None
    for t in texts:
        tier, amt = find_total_in_text(t)
        if amt is None:
            continue
        if best is None or tier < best[0]:
            best = (tier, amt)

    total = best[1] if best else None
    return date, format_amount(total)


def main():
    files = sorted(f for f in os.listdir(IMG_DIR)
                   if f.lower().endswith((".jpg", ".jpeg", ".png")))

    results = []
    for f in files:
        p = IMG_DIR / f
        try:
            date, total = process(p)
        except Exception as e:
            print(f"ERROR {f}: {e}")
            date, total = None, None
        print(f"{f}: date={date} total={total}")
        results.append((f, date, total))

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for f, d, t in results:
        ws.append([f, d, t])
    wb.save(OUT_XLSX)
    print(f"Saved to {OUT_XLSX}")


if __name__ == "__main__":
    main()
